/// 別の曲（またはリピートの2周目）に移ったときに、前の再生が完走だったかを判定する
private func close(_ play: ActivePlay, handingOffTo s: PlaybackSnapshot,
                            sameTrack: Bool, events: inout [TrackerEvent]) {
    guard play.isEligible else { return }
    var play = play
    let skipReason: DiscardReason = sameTrack ? .restarted : .skipped
    let duration = play.track.durationMs
    let dt = s.observedAt.timeIntervalSince(play.last.observedAt)
    let jitter = config.jitterTolerance + max(s.uncertainty, play.last.uncertainty)

    switch play.phase {
    case .playing(let run):
        let projectedEnd = run.songZero.addingTimeInterval(seconds(duration))
        if s.isPlaying {
            let switchAt = s.songZero  // 次のものが0秒目だった時刻
            if switchAt < projectedEnd.addingTimeInterval(-config.crossfade - jitter) {
                discard(&play, skipReason, at: s.observedAt, events: &events)
            } else if switchAt > projectedEnd.addingTimeInterval(jitter)
                        && (dt > config.maxUnverifiedGap || play.sawIdleSinceLast) {
                discard(&play, .unverifiableGap, at: s.observedAt, events: &events)
            } else {
                complete(&play, events: &events)
            }
        } else {
            if projectedEnd > s.observedAt.addingTimeInterval(jitter) {
                discard(&play, skipReason, at: s.observedAt, events: &events)
            } else if dt > config.maxUnverifiedGap || play.sawIdleSinceLast {
                discard(&play, .unverifiableGap, at: s.observedAt, events: &events)
            } else {
                complete(&play, events: &events)
            }
        }
    case .paused(let pausedMs):
        if pausedMs >= duration - crossfadeMs - tolerance(s, play.last) {
            complete(&play, events: &events)
        } else {
            discard(&play, skipReason, at: s.observedAt, events: &events)
        }
    }
}

