func isAcceptable(_ path: [GeoPoint], for leg: [TimedCoordinate]) -> Bool {
    guard path.count >= 2 else { return false }
    let raw = leg.map(\.coordinate)
    // 間引いた区間はほぼ直線なので、端点間の直線距離と比べて遠回りを見つける
    let straight = raw[0].distance(to: raw[raw.count - 1])
    let length = Geo.length(path)
    if length > max(straight * config.maxDetourRatio, straight + config.maxDetourExtra) { return false }
    // GPSの点がすべて経路の近くにある
    if raw.contains(where: { Geo.project($0, onto: path).distance > config.maxDeviation }) { return false }
    // 経路がGPSの軌跡から離れていない（別の道・寄り道）
    return Geo.sample(path, every: 20).allSatisfy { Geo.project($0, onto: raw).distance <= config.maxDeviation }
}

