/// 単調増加への最小二乗の当てはめ（pool adjacent violators）
static func isotonic(_ values: [Double]) -> [Double] {
    var blocks: [(sum: Double, count: Int)] = []
    for v in values {
        blocks.append((v, 1))
        while blocks.count > 1 {
            let last = blocks[blocks.count - 1], previous = blocks[blocks.count - 2]
            guard previous.sum / Double(previous.count) > last.sum / Double(last.count) else { break }
            blocks.removeLast()
            blocks[blocks.count - 1] = (previous.sum + last.sum, previous.count + last.count)
        }
    }
    return blocks.flatMap { Array(repeating: $0.sum / Double($0.count), count: $0.count) }
}
